def parser(log: str) -> dict[str, str]:
    import re
    import json

    results: dict[str, str] = {}

    # Attempt to extract a JSON blob containing "testResults"
    for m in re.finditer(r"\{.*?\"testResults\"\s*:\s*\[", log, flags=re.S):
        start_index = m.start()
        brace_level = 0
        end_index = None
        for i, ch in enumerate(log[start_index:], start=start_index):
            if ch == "{":
                brace_level += 1
            elif ch == "}":
                brace_level -= 1
                if brace_level == 0:
                    end_index = i + 1
                    break
        if end_index is None:
            continue
        candidate = log[start_index:end_index]
        try:
            data = json.loads(candidate)
            tr = data.get("testResults", [])
            for suite in tr:
                for ar in suite.get("assertionResults", []):
                    name = ar.get("fullName") or ar.get("title")
                    status = (ar.get("status") or "").lower()
                    if not name:
                        continue
                    if status in ("passed", "pass"):
                        results[name] = "pass"
                    elif status in ("failed", "fail", "xfailed", "xpass", "error"):
                        results[name] = "fail"
                    elif status in ("skipped", "pending", "todo"):
                        results[name] = "skip"
            if results:
                return results
        except Exception:
            # Fall through to regex parsing
            pass

    # Fallback: parse lines like "path/to/test.ts::test_name PASSED"
    fallback_re = re.compile(r"(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|PENDING|TODO|ERROR)", re.IGNORECASE)
    for line in log.splitlines():
        m = fallback_re.search(line)
        if not m:
            continue
        test_name, status = m.groups()
        status = status.upper()
        if status == "PASSED":
            results[test_name] = "pass"
        elif status in ("FAILED", "ERROR"):
            results[test_name] = "fail"
        elif status in ("SKIPPED", "PENDING", "TODO"):
            results[test_name] = "skip"

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}
    last_package: str | None = None
    status_rank = {"pass": 0, "skip": 1, "fail": 2}

    def update(name: str, status: str) -> None:
        if not name or not status:
            return
        prev = results.get(name)
        if prev is None or status_rank[status] > status_rank.get(prev, -1):
            results[name] = status

    output_re = re.compile(r"--- (PASS|FAIL|SKIP): ([^\s]+)")

    for line in log.splitlines():
        if not line:
            continue
        line = line.rstrip("\n")
        obj = None
        if line.lstrip().startswith("{") and line.rstrip().endswith("}"):
            try:
                obj = json.loads(line)
            except json.JSONDecodeError:
                obj = None

        if obj is not None:
            pkg = obj.get("Package")
            if pkg:
                last_package = pkg

            action = obj.get("Action")
            test = obj.get("Test")
            if action in ("pass", "fail", "skip") and pkg and test:
                update(f"{pkg}/{test}", action)

            output = obj.get("Output")
            if output:
                for out_line in output.splitlines():
                    match = output_re.search(out_line)
                    if match:
                        status = match.group(1).lower()
                        test_name = match.group(2)
                        pkg_for_line = pkg or last_package
                        if pkg_for_line:
                            update(f"{pkg_for_line}/{test_name}", status)
            continue

        match = output_re.search(line)
        if match:
            status = match.group(1).lower()
            test_name = match.group(2)
            if last_package:
                update(f"{last_package}/{test_name}", status)

    return results

def parser(log: str) -> dict[str, str]:
    import io
    import re
    import xml.etree.ElementTree as ET

    results = {}

    def add_result(name: str, status: str) -> None:
        name = (name or "").strip()
        if not name:
            return
        if status not in ("pass", "fail", "skip"):
            status = "fail"
        if name in results:
            i = 2
            while f"{name}#{i}" in results:
                i += 1
            name = f"{name}#{i}"
        results[name] = status

    def local_name(tag: str) -> str:
        return tag.rsplit("}", 1)[-1] if "}" in tag else tag

    def parse_as_junit_xml(xml_text: str) -> bool:
        start = xml_text.find("<")
        if start == -1:
            return False
        xml_text2 = xml_text[start:].strip()

        candidates = [xml_text2]
        last_gt = xml_text2.rfind(">")
        if last_gt != -1:
            candidates.append(xml_text2[: last_gt + 1])

        for txt in candidates:
            try:
                suite_stack = []
                for event, elem in ET.iterparse(io.StringIO(txt), events=("start", "end")):
                    tag = local_name(elem.tag)

                    if event == "start":
                        if tag == "testsuite":
                            suite_stack.append((elem.attrib.get("name") or "").strip())
                        continue

                    if tag == "testcase":
                        tc_name = (elem.attrib.get("name") or "").strip()
                        classname = (elem.attrib.get("classname") or "").strip()

                        suite_name = ""
                        for s in reversed(suite_stack):
                            if s:
                                suite_name = s
                                break

                        if classname and tc_name:
                            full_name = f"{classname}::{tc_name}"
                        elif suite_name and tc_name:
                            full_name = f"{suite_name}::{tc_name}"
                        else:
                            full_name = classname or tc_name or suite_name

                        status = "pass"
                        for child in list(elem):
                            ctag = local_name(child.tag)
                            if ctag in ("failure", "error"):
                                status = "fail"
                                break
                            if ctag == "skipped":
                                status = "skip"

                        if status == "pass":
                            raw_status = (elem.attrib.get("status") or "").lower()
                            if raw_status in ("skipped", "skip"):
                                status = "skip"
                            elif raw_status in ("failure", "failed", "error"):
                                status = "fail"

                        add_result(full_name, status)
                        elem.clear()

                    elif tag == "testsuite":
                        if suite_stack:
                            suite_stack.pop()
                        elem.clear()

                return True
            except ET.ParseError:
                continue
        return False

    def parse_fallback_text(text: str) -> None:
        for m in re.finditer(
            r"(?m)^(?P<name>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|ERROR)\s*$",
            text,
        ):
            st = m.group("status")
            add_result(m.group("name"), "pass" if st == "PASSED" else ("skip" if st == "SKIPPED" else "fail"))

        for m in re.finditer(r"(?m)^---\s+(PASS|FAIL|SKIP):\s+(\S+)", text):
            add_result(m.group(2), {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}[m.group(1)])

        for m in re.finditer(
            r"(?m)^(?P<name>\w+\s+\([^)]+\))\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|skipped)\s*$",
            text,
        ):
            st = m.group("status")
            add_result(m.group("name"), "pass" if st == "ok" else ("skip" if st == "skipped" else "fail"))

    if not parse_as_junit_xml(log):
        parse_fallback_text(log)

    return dict(results)

