def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def normalize_name(name: str, classname: str) -> str:
        name = (name or "").strip()
        classname = (classname or "").strip()
        if classname and name:
            if name.startswith(classname):
                return name
            return f"{classname}.{name}"
        return name or classname

    def status_from_testcase(tc: ET.Element) -> str:
        # Child elements
        has_failure = tc.find(".//failure") is not None or tc.find(".//error") is not None
        has_skipped = tc.find(".//skipped") is not None
        if has_failure:
            return "fail"
        if has_skipped:
            return "skip"
        # Attributes
        status_attr = (tc.get("status") or tc.get("result") or "").lower()
        if status_attr in {"skipped", "skip", "notrun", "disabled", "ignored"}:
            return "skip"
        if status_attr in {"fail", "failed", "error", "errors"}:
            return "fail"
        return "pass"

    def parse_xml_block(xml_text: str) -> None:
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return

        # Iterate all testcases, handle namespaces
        for tc in root.findall(".//{*}testcase"):
            name = tc.get("name")
            classname = tc.get("classname")
            full_name = normalize_name(name, classname)
            if not full_name:
                continue
            results[full_name] = status_from_testcase(tc)

    # Extract XML blocks that look like JUnit/CTest
    xml_blocks = []
    # Prefer full <testsuites> or <testsuite> blocks
    for pattern in (r"(<testsuites[\s\S]*?</testsuites>)", r"(<testsuite[\s\S]*?</testsuite>)"):
        xml_blocks.extend(re.findall(pattern, log, flags=re.IGNORECASE))
    # If none found, try from first <?xml to end
    if not xml_blocks:
        xml_match = re.search(r"(<\?xml[\s\S]*?>[\s\S]*)", log)
        if xml_match:
            xml_blocks.append(xml_match.group(1))

    for block in xml_blocks:
        parse_xml_block(block)

    # Fallback to text parsing if no results
    if not results:
        # pytest style
        pytest_re = re.compile(r"^(?P<name>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b", re.MULTILINE)
        status_map = {
            "PASSED": "pass",
            "FAILED": "fail",
            "ERROR": "fail",
            "SKIPPED": "skip",
            "XFAIL": "skip",
            "XPASS": "fail",
        }
        for m in pytest_re.finditer(log):
            results[m.group("name")] = status_map[m.group("status")]

        # unittest style
        unittest_re = re.compile(r"^(?P<name>\w+(?:\.\w+)*)\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|SKIPPED)\b", re.MULTILINE)
        for m in unittest_re.finditer(log):
            status = m.group("status").lower()
            results[m.group("name")] = "pass" if status == "ok" else ("skip" if status == "skipped" else "fail")

        # Go test
        go_re = re.compile(r"^---\s+(?P<status>PASS|FAIL|SKIP):\s+(?P<name>\S+)", re.MULTILINE)
        for m in go_re.finditer(log):
            status = m.group("status")
            results[m.group("name")] = {"PASS": "pass", "FAIL": "fail", "SKIP": "skip"}[status]

        # Jest style
        jest_re = re.compile(r"^(?P<symbol>✓|✕|○)\s+(?P<name>.+)$", re.MULTILINE)
        for m in jest_re.finditer(log):
            symbol = m.group("symbol")
            status = "pass" if symbol == "✓" else ("skip" if symbol == "○" else "fail")
            results[m.group("name").strip()] = status

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def norm_status(value: str) -> str:
        v = value.lower()
        if v in {"pass", "passed", "ok", "success"}:
            return "pass"
        if v in {"skip", "skipped", "xfail", "xfailed", "notrun", "suppressed", "expected failure"}:
            return "skip"
        return "fail"

    def status_from_case(case: dict) -> str:
        status_field = str(case.get("status", "")).upper()
        result_field = str(case.get("result", "")).upper()
        if status_field in {"DISABLED", "NOTRUN"}:
            return "skip"
        if case.get("disabled"):
            return "skip"
        if result_field in {"SKIPPED", "SUPPRESSED", "NOTRUN"}:
            return "skip"
        if "skipped" in case and case.get("skipped"):
            return "skip"

        failures = case.get("failures")
        errors = case.get("errors")
        if isinstance(failures, (list, dict, str)) and failures:
            return "fail"
        if isinstance(errors, (list, dict, str)) and errors:
            return "fail"
        if status_field in {"FAILED", "FAIL", "ERROR"}:
            return "fail"
        if result_field in {"FAILED", "FAILURE", "ERROR", "CRASHED"}:
            return "fail"

        return "pass"

    def record_case(name: str | None, classname: str | None, status: str) -> None:
        if not name and classname:
            test_name = classname
        elif name and classname and name != classname:
            test_name = f"{classname}.{name}"
        else:
            test_name = name or ""
        if test_name:
            results[test_name] = status

    def traverse_json(obj, current_suite: str | None = None):
        if isinstance(obj, list):
            for item in obj:
                traverse_json(item, current_suite)
            return
        if not isinstance(obj, dict):
            return

        name = obj.get("name")
        classname = obj.get("classname")
        child_keys = [k for k in ("testsuites", "testsuite", "testcase") if k in obj]
        is_leaf = not child_keys

        # If this dict looks like a testcase or is a leaf with a name, record it.
        if name and is_leaf:
            suite_name = classname or current_suite
            record_case(name, suite_name, status_from_case(obj))

        # Update suite context if this is a suite
        suite_name = current_suite
        if child_keys and name:
            suite_name = f"{current_suite}.{name}" if current_suite else name

        for key in child_keys:
            traverse_json(obj[key], suite_name)

    # Parse multiple JSON blobs in the log.
    decoder = json.JSONDecoder()
    idx = 0
    while idx < len(log):
        start = log.find("{", idx)
        if start == -1:
            break
        try:
            data, offset = decoder.raw_decode(log[start:])
            idx = start + offset
        except Exception:
            idx = start + 1
            continue
        if isinstance(data, dict) and any(k in data for k in ("testsuites", "testsuite", "testcase", "tests")):
            traverse_json(data)

    # Parse XML blocks (JUnit/TestNG)
    if "<testsuite" in log or "<testsuites" in log:
        xml_candidates = []
        xml_candidates += [m.start() for m in re.finditer(r"<testsuites[\s>]", log)]
        xml_candidates += [m.start() for m in re.finditer(r"<testsuite[\s>]", log)]
        for start in xml_candidates:
            fragment = log[start:]
            end = fragment.rfind("</testsuites>")
            if end != -1:
                frag = fragment[: end + len("</testsuites>")]
            else:
                end = fragment.rfind("</testsuite>")
                if end == -1:
                    continue
                frag = fragment[: end + len("</testsuite>")]
            try:
                root = ET.fromstring(frag)
            except Exception:
                continue

            def handle_xml(elem, suite_prefix=""):
                if elem.tag == "testsuite":
                    suite_name = elem.attrib.get("name") or suite_prefix
                    for child in elem:
                        handle_xml(child, suite_name)
                elif elem.tag == "testcase":
                    name = elem.attrib.get("name")
                    classname = elem.attrib.get("classname") or suite_prefix
                    status = "pass"
                    for child in elem:
                        tag = child.tag.lower()
                        if tag in {"failure", "error"}:
                            status = "fail"
                            break
                        if tag == "skipped":
                            status = "skip"
                    record_case(name, classname, status)
                else:
                    for child in elem:
                        handle_xml(child, suite_prefix)

            handle_xml(root)

    # Text parsing
    last_unittest = None

    for raw in log.splitlines():
        stripped = raw.strip()

        # GoogleTest text output
        m = re.match(r"^\[\s*RUN\s*\]\s+(\S+)", stripped)
        if m:
            continue
        m = re.match(r"^\[\s*(OK|FAILED|SKIPPED)\s*\]\s+(\S+)", stripped)
        if m:
            results[m.group(2)] = norm_status(m.group(1))
            continue

        # pytest verbose lines
        m = re.match(r"^(\S+::\S+.*?)\s+(PASSED|FAILED|SKIPPED|XFAIL|XPASS|ERROR)\b", stripped)
        if m:
            results[m.group(1)] = norm_status(m.group(2))
            continue
        # pytest summary lines: FAILED path::test
        m = re.match(r"^(FAILED|ERROR|SKIPPED|XFAIL|XPASS)\s+\[?\d*\]?\s*(\S+::\S+)", stripped)
        if m:
            results[m.group(2)] = norm_status(m.group(1))
            continue

        # unittest inline: test (module.Class) ... ok/FAIL
        m = re.match(r"^(\w[\w\.]*)\s+\(([^)]+)\)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped|xfail|expected failure)\b", stripped, re.IGNORECASE)
        if m:
            results[f"{m.group(2)}.{m.group(1)}"] = norm_status(m.group(3))
            last_unittest = None
            continue

        # unittest start line: test (module.Class)
        m = re.match(r"^(\w[\w\.]*)\s+\(([^)]+)\)\s*$", stripped)
        if m:
            last_unittest = f"{m.group(2)}.{m.group(1)}"
            continue

        # unittest continuation
        m = re.match(r"^(?:\.\.\.\s*)?(ok|FAIL|ERROR|skipped|xfail|expected failure)\b", stripped, re.IGNORECASE)
        if m and last_unittest:
            results[last_unittest] = norm_status(m.group(1))
            last_unittest = None
            continue

        # unittest without class: test_name ... ok
        m = re.match(r"^(\w[\w\.]*)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped|xfail|expected failure)\b", stripped, re.IGNORECASE)
        if m:
            results[m.group(1)] = norm_status(m.group(2))
            continue

        # nose/unittest failure summary: FAIL: test (module.Class)
        m = re.match(r"^(FAIL|ERROR):\s+(\w[\w\.]*)\s+\(([^)]+)\)", stripped)
        if m:
            results[f"{m.group(3)}.{m.group(2)}"] = norm_status(m.group(1))
            continue

        # Go test
        m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", stripped)
        if m:
            results[m.group(2)] = norm_status(m.group(1))
            continue

        # TAP
        m = re.match(r"^(not ok|ok)\s+\d*\s*-?\s*(.*)", stripped, re.IGNORECASE)
        if m:
            name = m.group(2).strip() or f"tap_{m.group(1)}"
            status = "pass" if m.group(1).lower() == "ok" else "fail"
            if "# skip" in stripped.lower():
                status = "skip"
            results[name] = status
            continue

        # Jest-like symbols
        m = re.match(r"^[\s]*([✓✕○])\s+(.+)", stripped)
        if m:
            symbol = m.group(1)
            name = m.group(2).strip()
            results[name] = "pass" if symbol == "✓" else "skip" if symbol == "○" else "fail"
            continue

        # Simple "PASS: testname" or "FAIL: testname"
        m = re.match(r"^(PASS|FAIL|SKIP)\s*[:\-]\s*(.+)", stripped, re.IGNORECASE)
        if m:
            results[m.group(2).strip()] = norm_status(m.group(1))
            continue

    return results

def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def worst_status(a: str, b: str) -> str:
        order = {"pass": 0, "skip": 1, "fail": 2}
        return a if order.get(a, 0) >= order.get(b, 0) else b

    def update_result(key: str, status: str) -> None:
        if not key:
            return
        prev = results.get(key)
        if prev:
            results[key] = worst_status(prev, status)
        else:
            results[key] = status

    def clean_xml(text: str) -> str:
        return re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", text)

    def status_from_element(elem: ET.Element) -> str:
        # Check attributes
        for attr_key in ("status", "result", "outcome"):
            val = (elem.attrib.get(attr_key) or "").lower()
            if val in ("fail", "failed", "error", "failure"):
                return "fail"
            if val in ("skip", "skipped"):
                return "skip"
            if val in ("pass", "passed", "success", "ok"):
                return "pass"
        # Check descendant tags
        status = "pass"
        for child in elem.iter():
            if child is elem:
                continue
            tag = child.tag.split("}")[-1]
            if tag in ("failure", "error"):
                return "fail"
            if tag == "skipped":
                status = "skip"
        return status

    def walk(elem: ET.Element, suite_name: str | None = None) -> None:
        tag = elem.tag.split("}")[-1]
        if tag == "testsuite":
            suite_name = elem.attrib.get("name") or suite_name
        if tag == "testcase":
            classname = (
                elem.attrib.get("classname")
                or elem.attrib.get("class")
                or suite_name
                or ""
            )
            name = (
                elem.attrib.get("name")
                or elem.attrib.get("id")
                or elem.attrib.get("method")
                or ""
            )
            if name:
                key = f"{classname}::{name}" if classname else name
                update_result(key, status_from_element(elem))
        for child in list(elem):
            walk(child, suite_name)

    def parse_xml_fragment(xml_text: str) -> None:
        xml_text = clean_xml(xml_text.strip())
        if not xml_text:
            return
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            # fallback to regex testcase parsing
            parse_testcase_regex(xml_text)
            return
        walk(root)

    def parse_testcase_regex(text: str) -> None:
        # Parse full testcase blocks
        for m in re.finditer(r"<testcase\b([^>]*)>(.*?)</testcase>", text, re.S):
            attrs = m.group(1)
            body = m.group(2)
            name = re.search(r'\bname="([^"]+)"', attrs)
            classname = re.search(r'\bclassname="([^"]+)"', attrs)
            n = name.group(1) if name else ""
            c = classname.group(1) if classname else ""
            status = "pass"
            if re.search(r"<(failure|error)\b", body):
                status = "fail"
            elif re.search(r"<skipped\b", body):
                status = "skip"
            if n:
                key = f"{c}::{n}" if c else n
                update_result(key, status)
        # Parse self-closing testcase tags
        for m in re.finditer(r"<testcase\b([^>]*)/>", text):
            attrs = m.group(1)
            name = re.search(r'\bname="([^"]+)"', attrs)
            classname = re.search(r'\bclassname="([^"]+)"', attrs)
            n = name.group(1) if name else ""
            c = classname.group(1) if classname else ""
            if n:
                key = f"{c}::{n}" if c else n
                update_result(key, "pass")

    def collect_xml_fragments(text: str) -> list[str]:
        fragments: list[tuple[int, int, str]] = []
        for pattern in (r"<testsuites\b[\s\S]*?</testsuites>", r"<testsuite\b[\s\S]*?</testsuite>"):
            for m in re.finditer(pattern, text):
                fragments.append((m.start(), m.end(), m.group(0)))
        if not fragments:
            return []
        # Remove fragments contained in larger fragments
        fragments.sort(key=lambda x: (x[0], -(x[1] - x[0])))
        kept: list[tuple[int, int, str]] = []
        for start, end, frag in fragments:
            if any(start >= ks and end <= ke for ks, ke, _ in kept):
                continue
            kept.append((start, end, frag))
        return [frag for _, _, frag in kept]

    # Parse XML fragments if available
    xml_fragments = collect_xml_fragments(log)
    if xml_fragments:
        for frag in xml_fragments:
            parse_xml_fragment(frag)
    else:
        # Try parsing entire log as XML
        if "<testcase" in log:
            parse_testcase_regex(log)

    # Parse common text-based outputs (pytest, unittest, go test, jest)
    for line in log.splitlines():
        line = line.rstrip()

        # pytest style: file.py::test_name PASSED/FAILED/SKIPPED/ERROR
        m = re.match(r"(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", line)
        if m:
            name = m.group(1)
            status = m.group(2).lower()
            status = "fail" if status in ("failed", "error") else "skip" if status == "skipped" else "pass"
            update_result(name, status)
            continue

        # unittest style: TestClass.test_method ... ok/FAIL/ERROR/skipped
        m = re.match(r"(\S+\.\S+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", line, re.I)
        if m:
            name = m.group(1)
            res = m.group(2).lower()
            status = "pass" if res == "ok" else "skip" if res == "skipped" else "fail"
            update_result(name, status)
            continue

        # go test: --- PASS: TestName
        m = re.match(r"---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
        if m:
            name = m.group(2)
            res = m.group(1).lower()
            status = "pass" if res == "pass" else "skip" if res == "skip" else "fail"
            update_result(name, status)
            continue

        # jest: ✓ test name / ✕ test name / ○ test name
        m = re.match(r"\s*(✓|✕|×|○)\s+(.+)", line)
        if m:
            symbol = m.group(1)
            name = m.group(2).strip()
            status = "pass" if symbol == "✓" else "skip" if symbol == "○" else "fail"
            update_result(name, status)

    return results

def parser(log: str) -> dict[str, str]:
    import re

    def strip_ansi(s: str) -> str:
        # Remove ANSI CSI/OSC/other escape sequences
        ansi = re.compile(
            r"(?:\x1B[@-Z\\-_]|\x1B\[[0-?]*[ -/]*[@-~]|\x1B\][^\x07]*(?:\x07|\x1B\\))"
        )
        return ansi.sub("", s)

    def norm_status(raw: str) -> str | None:
        rl = raw.strip().lower()
        if rl in {"ok", "pass", "passed", "success"}:
            return "pass"
        if rl in {"ignored", "skipped", "skip", "filtered out", "xfail", "xfailed"}:
            return "skip"
        if rl in {"failed", "fail", "failure", "error", "errored"}:
            return "fail"
        if rl in {"measured", "bench"}:
            return "pass"
        return None

    results: dict[str, str] = {}
    pending: set[str] = set()

    # Rust libtest
    libtest_done = re.compile(
        r"^\s*test\s+(?P<name>.+?)\s+\.\.\.\s+(?P<status>ok|FAILED|ignored|measured|bench|filtered out)\s*$"
    )
    libtest_start = re.compile(r"^\s*test\s+(?P<name>.+?)\s+\.\.\.\s*$")

    # trycmd (common)
    trycmd = re.compile(
        r"^\s*(?:Testing|Test)\s+(?P<name>.+?)\s+\.\.\.\s+(?P<status>ok|FAILED|ignored|skipped)\b"
    )

    # pytest
    pytest = re.compile(
        r"^\s*(?P<name>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|XFAIL|XPASS|ERROR)\b"
    )

    # Go test
    gotest = re.compile(r"^\s*---\s+(?P<status>PASS|FAIL|SKIP):\s+(?P<name>\S+)\b")

    # unittest
    unittest = re.compile(
        r"^\s*(?P<name>test\w+\s+\([^)]+\))\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|skipped)\b"
    )

    for raw_line in log.splitlines():
        s = strip_ansi(raw_line).strip()
        if not s:
            continue

        m = libtest_done.match(s)
        if m:
            name = m.group("name").strip()
            results[name] = norm_status(m.group("status")) or "fail"
            pending.discard(name)
            continue

        m = trycmd.match(s)
        if m:
            name = m.group("name").strip()
            results[name] = norm_status(m.group("status")) or "fail"
            continue

        m = pytest.match(s)
        if m:
            name = m.group("name").strip()
            results[name] = norm_status(m.group("status")) or "fail"
            continue

        m = gotest.match(s)
        if m:
            name = m.group("name").strip()
            results[name] = norm_status(m.group("status")) or "fail"
            continue

        m = unittest.match(s)
        if m:
            name = m.group("name").strip()
            results[name] = norm_status(m.group("status")) or "fail"
            continue

        m = libtest_start.match(s)
        if m:
            name = m.group("name").strip()
            if name not in results:
                pending.add(name)
            continue

    # Incomplete tests (seen start, no completion)
    for name in pending:
        results.setdefault(name, "fail")

    return results

def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}
    priority = {"pass": 0, "skip": 1, "fail": 2}

    def update(name: str, status: str) -> None:
        if not name:
            return
        cur = results.get(name)
        if cur is None or priority[status] > priority[cur]:
            results[name] = status

    def parse_xml(xml_text: str) -> bool:
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return False
        for case in root.findall(".//testcase"):
            name = case.get("name") or case.get("classname") or ""
            if not name:
                continue
            status = "pass"
            if case.find("skipped") is not None:
                status = "skip"
            if case.find("failure") is not None or case.find("error") is not None:
                status = "fail"
            update(name, status)
        return True

    # Parse XML segments if possible.
    segments = re.findall(r"<testsuites?[\s\S]*?</testsuites?>", log)
    if not segments:
        segments = re.findall(r"<testsuite[\s\S]*?</testsuite>", log)
    for seg in segments:
        parse_xml(seg)

    # Try a single XML document if segments did not parse.
    if not results:
        start = log.find("<?xml")
        if start != -1:
            end = log.rfind("</testsuites>")
            end_tag = "</testsuites>"
            if end == -1:
                end = log.rfind("</testsuite>")
                end_tag = "</testsuite>"
            if end != -1:
                parse_xml(log[start : end + len(end_tag)])

    # Regex fallback for truncated/malformed XML.
    for m in re.finditer(
        r"<testcase\b[^>]*>(.*?)</testcase>", log, re.IGNORECASE | re.DOTALL
    ):
        full_tag = m.group(0)
        start_tag = re.match(r"<testcase\b[^>]*>", full_tag, re.IGNORECASE)
        if not start_tag:
            continue
        attrs = dict(
            re.findall(r'(\w+)\s*=\s*["\'](.*?)["\']', start_tag.group(0))
        )
        name = attrs.get("name") or attrs.get("classname") or ""
        body = m.group(1)
        status = "pass"
        if re.search(r"<\s*(failure|error)\b", body, re.IGNORECASE):
            status = "fail"
        elif re.search(r"<\s*skipped\b", body, re.IGNORECASE):
            status = "skip"
        elif attrs.get("status", "").lower() in ("notrun", "skipped", "skip", "disabled"):
            status = "skip"
        update(name, status)

    for m in re.finditer(r"<testcase\b[^>]*/>", log, re.IGNORECASE):
        tag = m.group(0)
        attrs = dict(re.findall(r'(\w+)\s*=\s*["\'](.*?)["\']', tag))
        name = attrs.get("name") or attrs.get("classname") or ""
        status = "pass"
        if attrs.get("status", "").lower() in ("notrun", "skipped", "skip", "disabled"):
            status = "skip"
        update(name, status)

    return results

def parser(log: str) -> dict[str, str]:
    import json

    results: dict[str, str] = {}
    # Prefer worse outcomes if multiple events occur for same test
    priority = {"fail": 3, "skip": 2, "pass": 1}

    for line in log.splitlines():
        s = line.strip()
        if not s or not s.startswith("{"):
            continue
        try:
            obj = json.loads(s)
        except Exception:
            continue
        if not isinstance(obj, dict):
            continue

        action = obj.get("Action")
        test = obj.get("Test")
        pkg = obj.get("Package")

        # Only consider test-level events
        if not test:
            continue

        if action == "pass":
            status = "pass"
        elif action == "fail":
            status = "fail"
        elif action == "skip":
            status = "skip"
        else:
            continue

        key = f"{pkg}::{test}" if pkg else test
        prev = results.get(key)
        if prev is None or priority[status] > priority.get(prev, 0):
            results[key] = status

    return results

