def parser(log: str) -> dict[str, str]:
    import re

    # Keep the worst status when duplicates occur: fail > pass > skip
    severity = {"skip": 0, "pass": 1, "fail": 2}
    results: dict[str, str] = {}

    def set_status(name: str, status: str):
        prev = results.get(name)
        if prev is None or severity[status] > severity[prev]:
            results[name] = status

    # TAP with index: "ok 12 - suite › test" or "not ok 3 - suite › test  # SKIP ..."
    tap_re = re.compile(
        r'^(ok|not ok)\s+\d+\s*-\s*(.*?)(?:\s+#\s*(SKIP|SKIPPED|TODO|XF?AIL|XPASS|skip|todo).*)?\s*$',
        re.IGNORECASE,
    )
    # TAP without index: "ok description" or "not ok description"
    tap_simple_re = re.compile(
        r'^(ok|not ok)\s+(?!\d+\s*-)(.*\S.*)$',
        re.IGNORECASE,
    )
    # cargo libtest verbose: "test path::to::test_name ... ok|FAILED|ignored"
    cargo_re = re.compile(
        r'^\s*test\s+([^\s]+)\s+\.\.\.\s+(ok|FAILED|ignored)\s*$',
        re.IGNORECASE,
    )

    for line in log.splitlines():
        line = line.rstrip("\r\n")

        m = tap_re.match(line)
        if m:
            status_word, name, flag = m.groups()
            name = (name or "").strip()
            if name:
                if status_word.lower() == "ok":
                    if flag:
                        set_status(name, "skip")
                    else:
                        set_status(name, "pass")
                else:
                    set_status(name, "fail")
            continue

        m = tap_simple_re.match(line)
        if m:
            status_word, name = m.groups()
            name = (name or "").strip()
            if name:
                if status_word.lower() == "ok":
                    set_status(name, "pass")
                else:
                    set_status(name, "fail")
            continue

        m = cargo_re.match(line)
        if m:
            name, status = m.groups()
            name = (name or "").strip()
            s = status.lower()
            if s == "ok":
                set_status(name, "pass")
            elif s == "failed":
                set_status(name, "fail")
            elif s == "ignored":
                set_status(name, "skip")
            continue

    return results

def parser(log: str) -> dict[str, str]:
    import json

    # Find and parse a JSON object in the log that contains "testResults"
    def extract_json_with_key(text: str, key: str):
        starts = [i for i, ch in enumerate(text) if ch == "{"]
        for start in starts:
            depth = 0
            in_str = False
            escape = False
            for end in range(start, len(text)):
                c = text[end]
                if in_str:
                    if escape:
                        escape = False
                    elif c == "\\":
                        escape = True
                    elif c == '"':
                        in_str = False
                    continue
                else:
                    if c == '"':
                        in_str = True
                        continue
                    if c == "{":
                        depth += 1
                    elif c == "}":
                        depth -= 1
                        if depth == 0:
                            chunk = text[start : end + 1]
                            if key in chunk:
                                try:
                                    return json.loads(chunk)
                                except Exception:
                                    pass
                            break
        return None

    obj = extract_json_with_key(log, '"testResults"')
    results: dict[str, str] = {}

    if isinstance(obj, dict) and "testResults" in obj:
        for suite in obj.get("testResults", []):
            for ar in suite.get("assertionResults", []):
                # Prefer fullName; fallback to ancestorTitles + title
                name = ar.get("fullName")
                if not name:
                    ancestors = " ".join(ar.get("ancestorTitles", []) or [])
                    title = ar.get("title") or ""
                    name = (ancestors + " " + title).strip()
                status = (ar.get("status") or "").lower()
                if status == "passed":
                    results[name] = "pass"
                elif status == "failed":
                    results[name] = "fail"
                elif status == "skipped":
                    results[name] = "skip"
    return results

def parser(log: str) -> dict[str, str]:
    import re
    results = {}
    ok_pattern = re.compile(r"\[\s+OK\s+\]\s+(\S+)\s+\(\d+ ms\)")
    fail_pattern = re.compile(r"\[\s+FAILED\s+\]\s+(\S+)\s+\(\d+ ms\)")
    skip_pattern = re.compile(r"\[\s+SKIPPED\s+\]\s+(\S+)\s+\(\d+ ms\)")
    for line in log.splitlines():
        m_ok = ok_pattern.search(line)
        if m_ok:
            results[m_ok.group(1)] = "pass"
            continue
        m_fail = fail_pattern.search(line)
        if m_fail:
            results[m_fail.group(1)] = "fail"
            continue
        m_skip = skip_pattern.search(line)
        if m_skip:
            results[m_skip.group(1)] = "skip"
            continue
    return results

def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    # Match all JUnit XML testsuite blocks in the log
    suites = re.findall(r'(<testsuite\b.*?</testsuite>)', log, flags=re.DOTALL)

    for suite_xml in suites:
        try:
            root = ET.fromstring(suite_xml)
        except Exception:
            # Skip any malformed XML fragments
            continue

        # Extract testcases
        for tc in root.findall(".//testcase"):
            name = tc.get("name", "").strip()
            classname = tc.get("classname", "").strip()
            test_id = f"{classname}.{name}" if classname else name

            # Default status is pass unless skipped/failure/error present
            status = "pass"
            if tc.find("skipped") is not None:
                status = "skip"
            elif tc.find("failure") is not None or tc.find("error") is not None:
                status = "fail"

            if test_id:
                results[test_id] = status

    return results

def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}

    def normalize_status(status: str | None) -> str | None:
        if not status:
            return None
        s = str(status).strip().lower()
        if s in ("passed", "pass", "ok", "success"):
            return "pass"
        if s in ("failed", "fail", "error", "timedout", "timeout", "failure"):
            return "fail"
        if s in ("skipped", "skip", "pending", "todo", "disabled", "ignored", "cancelled"):
            return "skip"
        return None

    def add_result(name: str | None, status: str, suite_name: str | None = None) -> None:
        if not name:
            return
        key = name
        if key in results:
            if suite_name:
                key = f"{suite_name}::{name}"
            if key in results:
                base = key
                idx = 2
                while key in results:
                    key = f"{base} #{idx}"
                    idx += 1
        results[key] = status

    def parse_assertions(container: dict) -> None:
        suites = []
        if isinstance(container.get("testResults"), list):
            suites = container["testResults"]
        else:
            suites = [container]

        for suite in suites:
            if not isinstance(suite, dict):
                continue
            suite_name = (
                suite.get("name")
                or suite.get("file")
                or suite.get("filepath")
                or suite.get("testFilePath")
            )
            assertions = (
                suite.get("assertionResults")
                or suite.get("assertions")
                or suite.get("tests")
                or []
            )
            if isinstance(assertions, dict):
                assertions = list(assertions.values())
            for case in assertions:
                if not isinstance(case, dict):
                    continue
                status = normalize_status(case.get("status"))
                if status is None:
                    status = normalize_status(case.get("outcome") or case.get("result"))
                if status is None:
                    continue
                name = case.get("fullName") or case.get("name") or case.get("title")
                if not name:
                    ancestors = case.get("ancestorTitles") or case.get("ancestors") or []
                    title = case.get("title") or case.get("name")
                    parts = [str(a) for a in ancestors if a]
                    if title:
                        parts.append(str(title))
                    if parts:
                        name = " ".join(parts)
                add_result(name, status, suite_name)

    # Attempt to parse JSON objects from the log (robust to noise)
    decoder = json.JSONDecoder()
    idx = 0
    while idx < len(log):
        start = log.find("{", idx)
        if start == -1:
            break
        try:
            obj, offset = decoder.raw_decode(log[start:])
        except Exception:
            idx = start + 1
            continue
        idx = start + offset
        if isinstance(obj, dict):
            if "testResults" in obj or "assertionResults" in obj:
                parse_assertions(obj)

    if results:
        return results

    # Fallback regex parsing for non-JSON outputs
    for line in log.splitlines():
        line = line.strip()
        if not line:
            continue

        # pytest
        m = re.search(r"(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)", line)
        if m:
            status = normalize_status(m.group(2))
            if status:
                add_result(m.group(1), status)
            continue

        # go test
        m = re.search(r"---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
        if m:
            status = normalize_status(m.group(1))
            if status:
                add_result(m.group(2), status)
            continue

        # jest symbols
        m = re.search(r"^(✓|✔|✕|×|✗|○|◌)\s+(.+)$", line)
        if m:
            symbol = m.group(1)
            status = {
                "✓": "pass",
                "✔": "pass",
                "✕": "fail",
                "×": "fail",
                "✗": "fail",
                "○": "skip",
                "◌": "skip",
            }.get(symbol)
            if status:
                add_result(m.group(2).strip(), status)
            continue

        # TAP
        m = re.search(r"^(ok|not ok)\s+\d+\s+-\s+(.+)$", line, re.IGNORECASE)
        if m:
            status = "pass" if m.group(1).lower() == "ok" else "fail"
            add_result(m.group(2).strip(), status)
            continue

        # unittest style: name ... ok/FAIL/ERROR/SKIP
        m = re.search(r"^(.*?)\s+\.\.\.\s+(ok|FAIL|ERROR|SKIP|SKIPPED)$", line, re.IGNORECASE)
        if m:
            status = normalize_status(m.group(2))
            if status:
                add_result(m.group(1).strip(), status)
            continue

    return results

def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def update_result(name: str, status: str) -> None:
        if not name:
            return
        priority = {"pass": 0, "skip": 1, "fail": 2}
        prev = results.get(name)
        if prev is None or priority[status] > priority[prev]:
            results[name] = status

    def localname(tag: str) -> str:
        return tag.split("}", 1)[-1] if tag else ""

    def parse_testcase(elem: ET.Element, suite_name: str) -> None:
        name = elem.get("name") or ""
        classname = elem.get("classname") or ""
        if classname:
            full = f"{classname}::{name}" if name else classname
        elif suite_name:
            full = f"{suite_name}::{name}" if name else suite_name
        else:
            full = name
        status = "pass"
        for child in list(elem):
            tag = localname(child.tag).lower()
            if tag in ("failure", "error"):
                status = "fail"
                break
            if tag == "skipped":
                status = "skip"
        update_result(full, status)

    def traverse(elem: ET.Element, suite_name: str = "") -> None:
        tag = localname(elem.tag).lower()
        if tag == "testsuite":
            suite_name = elem.get("name") or suite_name
        if tag == "testcase":
            parse_testcase(elem, suite_name)
        for child in list(elem):
            traverse(child, suite_name)

    def safe_parse_xml(xml_text: str) -> None:
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return
        traverse(root)

    # Clean invalid control chars
    cleaned_log = re.sub(r"[\x00-\x08\x0b\x0c\x0e-\x1f]", "", log)

    # 1) Try parsing wrapped XML (handles multiple suites)
    wrapped = re.sub(r"<\?xml[^>]*\?>", "", cleaned_log)
    wrapped = re.sub(r"<!DOCTYPE[^>]*>", "", wrapped)
    try:
        root = ET.fromstring(f"<root>{wrapped}</root>")
        traverse(root)
    except ET.ParseError:
        pass

    # 2) Parse individual <testsuite> fragments
    suites = re.findall(r"<testsuite\b[\s\S]*?</testsuite>", cleaned_log)
    suites += re.findall(r"<testsuite\b[^>]*?/>", cleaned_log)
    for suite in suites:
        safe_parse_xml(suite)

    # 3) Fallback: parse individual <testcase> fragments if XML parsing failed
    testcase_fragments = re.findall(r"<testcase\b[\s\S]*?</testcase>", cleaned_log)
    testcase_fragments += re.findall(r"<testcase\b[^>]*?/>", cleaned_log)
    for frag in testcase_fragments:
        try:
            elem = ET.fromstring(frag)
        except ET.ParseError:
            continue
        parse_testcase(elem, elem.get("classname") or "")

    # 4) Parse common plaintext test outputs
    for line in cleaned_log.splitlines():
        line = line.strip()

        # pytest style
        m = re.match(r"^(\S+::\S+)\s+(PASSED|FAILED|SKIPPED|ERROR|XFAIL|XPASS)\b", line)
        if m:
            name, status = m.group(1), m.group(2)
            status = status.lower()
            if status in ("failed", "error", "xpass"):
                update_result(name, "fail")
            elif status in ("skipped", "xfail"):
                update_result(name, "skip")
            else:
                update_result(name, "pass")
            continue

        # unittest style
        m = re.match(r"^(\w[\w\.]+)\s+\.\.\.\s+(ok|FAIL|ERROR|skipped)\b", line, re.IGNORECASE)
        if m:
            name, status = m.group(1), m.group(2).lower()
            if status in ("fail", "error"):
                update_result(name, "fail")
            elif status == "skipped":
                update_result(name, "skip")
            else:
                update_result(name, "pass")
            continue

        # Go test style
        m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
        if m:
            status, name = m.group(1).lower(), m.group(2)
            update_result(name, "fail" if status == "fail" else ("skip" if status == "skip" else "pass"))
            continue

        # Jest style symbols
        m = re.match(r"^[✓√]\s+(.+)$", line)
        if m:
            update_result(m.group(1).strip(), "pass")
            continue
        m = re.match(r"^[✕x×]\s+(.+)$", line)
        if m:
            update_result(m.group(1).strip(), "fail")
            continue
        m = re.match(r"^[○◌]\s+(.+)$", line)
        if m:
            update_result(m.group(1).strip(), "skip")
            continue

        # Generic PASS/FAIL lines
        m = re.match(r"^(PASS|FAIL|SKIP)\s+(.+)$", line)
        if m:
            status, name = m.group(1).lower(), m.group(2).strip()
            update_result(name, "fail" if status == "fail" else ("skip" if status == "skip" else "pass"))

    return results
